#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){long long n;scanf("%lld",&n);
if(n<2){printf("%lld\n",n);return 0;}
long long lo=1,hi=n;
while(lo<hi){long long mid=lo+(hi-lo+1)/2;
if(mid*mid<=n)lo=mid;else hi=mid-1;}
printf("%lld\n",lo);return 0;}

